extends Node3D
class_name TunisNightLifePass

var medium_detail_nodes: Array[Node3D] = []
var high_detail_nodes: Array[Node3D] = []
var night_lights: Array[OmniLight3D] = []
var emissive_signs: Array[MeshInstance3D] = []
var current_detail_level := 2
var clock: WorldClock
var _night_active := false
var _blackout_active := false

func build() -> void:
    add_to_group("quality_visual_detail")
    _build_shop_lights()
    _build_neon_signs()
    _build_cafe_lights()
    apply_visual_budget(current_detail_level)
    _refresh_power_state()

func configure(world_clock: WorldClock) -> void:
    clock = world_clock
    if clock != null and not clock.minute_changed.is_connected(_on_minute_changed):
        clock.minute_changed.connect(_on_minute_changed)
    if not GameState.blackout_changed.is_connected(_on_blackout_changed):
        GameState.blackout_changed.connect(_on_blackout_changed)
    _blackout_active = GameState.blackout_active
    _refresh_time_state()

func apply_visual_budget(detail_level: int) -> void:
    current_detail_level = clampi(detail_level, 0, 2)
    for node in medium_detail_nodes:
        if is_instance_valid(node):
            node.visible = current_detail_level >= 1
    for node in high_detail_nodes:
        if is_instance_valid(node):
            node.visible = current_detail_level >= 2
    _refresh_power_state()

func _register(node: Node3D, minimum_level: int) -> Node3D:
    if minimum_level >= 2:
        high_detail_nodes.append(node)
    elif minimum_level == 1:
        medium_detail_nodes.append(node)
    return node

func _mat(color: Color, emission_color: Color = Color(0, 0, 0, 1)) -> StandardMaterial3D:
    var material := StandardMaterial3D.new()
    material.albedo_color = color
    material.roughness = 0.72
    if emission_color.r > 0.0 or emission_color.g > 0.0 or emission_color.b > 0.0:
        material.emission_enabled = true
        material.emission = emission_color
        material.emission_energy_multiplier = 2.2
    return material

func _box(parent: Node3D, pos: Vector3, size: Vector3, color: Color, emission: Color = Color(0, 0, 0, 1)) -> MeshInstance3D:
    var node := MeshInstance3D.new()
    var mesh := BoxMesh.new()
    mesh.size = size
    node.mesh = mesh
    node.position = pos
    node.material_override = _mat(color, emission)
    parent.add_child(node)
    return node

func _light(parent: Node3D, pos: Vector3, energy: float, range_m: float, color: Color) -> OmniLight3D:
    var light := OmniLight3D.new()
    light.position = pos
    light.light_energy = energy
    light.omni_range = range_m
    light.light_color = color
    light.shadow_enabled = false
    parent.add_child(light)
    night_lights.append(light)
    return light

func _build_shop_lights() -> void:
    var root := Node3D.new()
    root.name = "NightShopLights"
    add_child(root)
    _register(root, 1)
    var locations := [
        Vector3(-48.0, 3.2, -67.0),
        Vector3(29.0, 3.2, -67.0),
        Vector3(75.0, 3.2, -7.0),
        Vector3(-28.0, 3.2, 53.0)
    ]
    for pos in locations:
        _light(root, pos, 1.7, 9.0, Color("#ffd18a"))

func _build_neon_signs() -> void:
    var root := Node3D.new()
    root.name = "NightNeonSigns"
    add_child(root)
    _register(root, 2)
    var signs := [
        [Vector3(-48.0, 4.4, -66.8), Color("#f4c34e")],
        [Vector3(29.0, 4.4, -66.8), Color("#64c7ff")],
        [Vector3(75.0, 4.4, -6.8), Color("#f08b5a")]
    ]
    for entry in signs:
        var pos: Vector3 = entry[0]
        var glow: Color = entry[1]
        var sign := _box(root, pos, Vector3(5.5, 0.55, 0.12), glow.darkened(0.55), glow)
        emissive_signs.append(sign)

func _build_cafe_lights() -> void:
    var root := Node3D.new()
    root.name = "NightCafeLights"
    add_child(root)
    _register(root, 2)
    for x in [-54.0, -50.0, -46.0, -42.0]:
        _light(root, Vector3(x, 3.0, -61.5), 0.9, 5.0, Color("#ffbd72"))

func _on_minute_changed(_day: int, _hour: int, _minute: int) -> void:
    _refresh_time_state()

func _on_blackout_changed(active: bool) -> void:
    _blackout_active = active
    _refresh_power_state()

func _refresh_time_state() -> void:
    if clock == null:
        _night_active = false
    else:
        var hour := clock.current_hour()
        _night_active = hour >= 18 or hour < 6
    _refresh_power_state()

func _refresh_power_state() -> void:
    var powered := _night_active and not _blackout_active
    for light in night_lights:
        if is_instance_valid(light):
            light.visible = powered
    for sign in emissive_signs:
        if not is_instance_valid(sign):
            continue
        var parent := sign.get_parent() as Node3D
        sign.visible = powered and parent != null and parent.visible

