    for x in [-8.0, 8.0, 41.0]:
        _box(root, Vector3(x, 0.255, 8.0), Vector3(1.45, 0.035, 0.55), Color("#d8b83e"))

func _build_crossing_edge_markers() -> void:
    var root := Node3D.new()
    root.name = "ProtectedCrossingEdges"
    add_child(root)
    _register(root, 2)
    for x in [-10.2, 10.2, 38.8, 43.2]:
        _box(root, Vector3(x, 0.21, 7.82), Vector3(0.22, 0.34, 1.1), Color("#eeeeea"))

extends Node3D
class_name TunisPublicRealmPass

var generated_count := 0
var medium_detail_nodes: Array[Node3D] = []
var high_detail_nodes: Array[Node3D] = []
var current_detail_level := 2

func build() -> void:
    add_to_group("quality_visual_detail")
    _build_tree_grates()
    _build_drainage_grates()
    _build_curbstones()
    _build_pedestrian_barriers()
    apply_visual_budget(current_detail_level)

func apply_visual_budget(detail_level: int) -> void:
    current_detail_level = clampi(detail_level, 0, 2)
    var show_medium := current_detail_level >= 1
    var show_high := current_detail_level >= 2
    for node in medium_detail_nodes:
        if is_instance_valid(node):
            node.visible = show_medium
    for node in high_detail_nodes:
        if is_instance_valid(node):
            node.visible = show_high

func _register_detail(node: Node3D, minimum_level: int) -> Node3D:
    if minimum_level >= 2:
        high_detail_nodes.append(node)
    elif minimum_level == 1:
        medium_detail_nodes.append(node)
    return node

func _material(color: Color, roughness := 0.9, metallic := 0.0) -> StandardMaterial3D:
    var material := StandardMaterial3D.new()
    material.albedo_color = color
    material.roughness = roughness
    material.metallic = metallic
    return material

func _box(parent: Node3D, pos: Vector3, size: Vector3, color: Color) -> MeshInstance3D:
    var instance := MeshInstance3D.new()
    var mesh := BoxMesh.new()
    mesh.size = size
    instance.mesh = mesh
    instance.position = pos
    instance.material_override = _material(color)
    parent.add_child(instance)
    generated_count += 1
    return instance

func _cylinder(parent: Node3D, pos: Vector3, radius: float, height: float, color: Color) -> MeshInstance3D:
    var instance := MeshInstance3D.new()
    var mesh := CylinderMesh.new()
    mesh.top_radius = radius
    mesh.bottom_radius = radius
    mesh.height = height
    instance.mesh = mesh
    instance.position = pos
    instance.material_override = _material(color)
    parent.add_child(instance)
    generated_count += 1
    return instance

func _build_tree_grates() -> void:
    var root := Node3D.new()
    root.name = "SidewalkTreeGrates"
    add_child(root)
    for pos in [Vector3(-34, 0.13, 9.4), Vector3(8, 0.13, 9.4), Vector3(49, 0.13, 9.4)]:
        var plate := _box(root, pos, Vector3(1.7, 0.035, 1.7), Color("#535756"))
        _register_detail(plate, 1)
        for offset in [-0.55, -0.18, 0.18, 0.55]:
            var slot := _box(root, pos + Vector3(offset, 0.025, 0), Vector3(0.06, 0.025, 1.35), Color("#222625"))
            _register_detail(slot, 2)

func _build_drainage_grates() -> void:
    var root := Node3D.new()
    root.name = "StreetDrainage"
    add_child(root)
    for x in [-56.0, -12.0, 32.0, 76.0]:
        var grate := _box(root, Vector3(x, 0.115, 7.15), Vector3(1.2, 0.025, 0.42), Color("#353b3c"))
        _register_detail(grate, 1)
        for lane in range(5):
            var slot := _box(root, Vector3(x - 0.42 + lane * 0.21, 0.132, 7.15), Vector3(0.06, 0.012, 0.31), Color("#181b1c"))
            _register_detail(slot, 2)

func _build_curbstones() -> void:
    var root := Node3D.new()
    root.name = "PublicRealmCurbstones"
    add_child(root)
    _register_detail(root, 1)
    for i in range(11):
        var x := -50.0 + float(i) * 10.0
        _box(root, Vector3(x, 0.21, 8.0), Vector3(8.4, 0.28, 0.32), Color("#c4bca9"))

func _build_pedestrian_barriers() -> void:
    var root := Node3D.new()
    root.name = "PedestrianSafetyBarriers"
    add_child(root)
    _register_detail(root, 2)
    for x in [-11.5, -9.8, -8.1, 18.0, 19.7, 21.4]:
        _cylinder(root, Vector3(x, 0.54, -7.7), 0.08, 1.08, Color("#45494a"))
        _box(root, Vector3(x, 0.95, -7.7), Vector3(0.8, 0.08, 0.08), Color("#45494a"))

